/**
 * Call history (CDRs) for one user, or for the whole domain when `user` is
 * null. Used by the user panel's History tab and by Analyze.
 *
 * What the v46 lab taught (read-only probes against grant_wilderman_llc):
 *
 * - Pages are 100 rows. Past `limit=100` the switch silently returns a
 *   reduced record (no `call-orig-from-user`, no `call-through-action`), so a
 *   bigger page would quietly lose the caller's number. `start` is the offset
 *   (`offset` is ignored).
 * - `call-direction` is a number: 0 outbound, 1 inbound, 2 missed (never
 *   answered), 3 internal (extension to extension). A user's own list reports
 *   direction relative to that user and marks internal calls with `onnet: 1`
 *   instead of 3; on it, 2 also covers an internal call that went to their
 *   voicemail.
 * - `call-recording-status` is 0 on every lab CDR (no call there is recorded).
 * - Recordings: Horizon's own Call History plays them from
 *   `/domains/:d/vcon/:cdr?yyyymm=YYYYMM`, a vCon document whose `dialog` holds
 *   one `recording` entry per leg, with a `url` once a file exists. That route
 *   answers on the lab. The `/domains/:d/cdrs/:id/recording` route behind
 *   `ns.readCdrRecording` is not registered there (it answers "No Route Found",
 *   exactly like a made-up path), so it is only tried when the vCon read itself
 *   is missing.
 */
import type * as React from 'react';
import { useCallback, useEffect, useId, useMemo, useRef, useState } from 'react';
import type { DatagridAction, DatagridColumn, DatagridToolbarConfig, HorizonApiClient } from '@netsapiens/horizon-sdk';

import type { NsCdr, NsRecord } from '../types';
import * as ns from '../api/ns';
import { useSwitchboard } from '../data/SwitchboardData';
import { usePersistentState } from '../data/persist';
import { classifyError, describeReadError } from '../model/errors';
import { EMPTY_CELL, formatDateTime, formatElapsed, formatPhone, plural } from '../model/format';
import { usefulCallerName } from '../model/calls';
import { baseExtension, cleanNumber, first, lower, parseSwitchTime, pick, str, toFloat, toInt, yes } from '../model/raw';
import { useKit } from '../ui/kit';
import type { Kit } from '../ui/kit';
import { ActionIcon, Empty, SmallButton, toneText } from '../ui/bits';
import type { Tone } from '../ui/bits';
import { RangeToggle, isRangePreset, resolveRange } from '../views/analyze/range';
import type { RangePreset, RangeWindow } from '../views/analyze/range';

/** Rows per read. Do not raise: past 100 the switch drops fields (see above). */
const PAGE = 100;
/** "Load more" stops here; a longer history wants a shorter range. */
const MAX_ROWS = 1000;

export function CallHistorySection({ user }: { user: string | null }) {
  // Keyed by scope, so opening another user starts clean: no rows, pages or
  // playing recording carried over from the last one.
  const scope = user == null ? null : user.trim();
  if (scope === '') return <Empty>No user is selected.</Empty>;
  return <HistoryBody key={scope ?? '(domain)'} user={scope} />;
}

// ---------------------------------------------------------------------------
// Rows
// ---------------------------------------------------------------------------

type Direction = 'inbound' | 'outbound' | 'internal' | 'missed' | 'unknown';

const DIRECTION: Record<Direction, { label: string; icon: string; tone: Tone }> = {
  inbound: { label: 'Inbound', icon: 'lucide:phone-incoming', tone: 'info' },
  outbound: { label: 'Outbound', icon: 'lucide:phone-outgoing', tone: 'primary' },
  internal: { label: 'Internal', icon: 'lucide:arrow-left-right', tone: 'neutral' },
  missed: { label: 'Missed', icon: 'lucide:phone-missed', tone: 'error' },
  unknown: { label: 'Unknown', icon: 'lucide:phone', tone: 'neutral' },
};

function cdrDirection(r: NsRecord): Direction {
  const d = lower(r['call-direction']);
  if (d === '2' || d.startsWith('miss')) return 'missed';
  let dir: Direction = 'unknown';
  // "internal" before "in", or every internal call would read as inbound.
  if (d === '3' || d === 'internal' || d === 'on-net' || d === 'onnet') dir = 'internal';
  else if (d === '0' || d.startsWith('out')) dir = 'outbound';
  else if (d === '1' || d.startsWith('in')) dir = 'inbound';
  if (yes(r.onnet) && (dir === 'inbound' || dir === 'outbound')) dir = 'internal';
  return dir;
}

const NO_RECORDING = new Set(['', '0', 'none', 'no', 'false', 'off', 'disabled', 'not recorded', 'n/a', '-']);

/** Does the CDR say the call was recorded? Numeric statuses above 0 do, as does any status but "none". */
function recordedFlag(r: NsRecord): boolean {
  if (yes(r['has-recording'])) return true;
  const s = lower(r['call-recording-status']);
  if (/^\d+(\.\d+)?$/.test(s)) return Number(s) > 0;
  return !NO_RECORDING.has(s);
}

interface Party {
  /** The line a person reads: a name, else the formatted number. */
  primary: string;
  /** The number or extension behind a name, and anything else worth one short line. */
  secondary: string;
}

interface HistoryRow {
  id: string;
  /** The id the recording read is keyed by (the call's parent CDR). */
  cdrId: string;
  startedAt: number | null;
  direction: Direction;
  from: Party;
  to: Party;
  via: Party | null;
  talkSeconds: number;
  totalSeconds: number;
  result: string;
  voicemail: boolean;
  recorded: boolean;
}

/** An extension or phone number, formatted when it is a phone number. */
function numberText(n: string): string {
  return formatPhone(n) || n;
}

function toRow(r: NsCdr, index: number, names: ReadonlyMap<string, string>): HistoryRow {
  const direction = cdrDirection(r);
  const nameOf = (n: string) => (n ? names.get(n) ?? names.get(baseExtension(n)) ?? '' : '');

  // From: the caller. A directory extension shows its person's full name.
  const fromNumber = cleanNumber(pick(r, 'call-orig-from-user', 'call-orig-user', 'call-orig-from-uri'));
  const fromDirectory = nameOf(fromNumber);
  const fromRaw = pick(r, 'call-orig-from-name').replace(/\s+/g, ' ');
  const fromName = fromDirectory || (usefulCallerName(fromRaw, fromNumber) ? fromRaw : '');
  const from: Party = {
    primary: fromName || numberText(fromNumber) || 'Unknown caller',
    secondary: fromName ? numberText(fromNumber) : '',
  };

  // To: who received it. Outbound, that is the number dialed; otherwise the
  // extension the call terminated on, with the dialed number when it adds
  // something (the public number an inbound caller used).
  const dialed = cleanNumber(pick(r, 'call-orig-to-user', 'call-orig-request-user'));
  const term = baseExtension(pick(r, 'call-term-user'));
  let to: Party;
  if (direction === 'outbound') {
    const n = dialed || term;
    const name = nameOf(n);
    to = { primary: name || numberText(n) || EMPTY_CELL, secondary: name ? n : '' };
  } else {
    const n = term || dialed;
    const name = nameOf(n);
    const extra = dialed && dialed !== n && dialed.length >= 7 ? `dialed ${numberText(dialed)}` : '';
    to = {
      primary: name || numberText(n) || EMPTY_CELL,
      secondary: [name ? n : '', extra].filter(Boolean).join(' · '),
    };
  }

  // Via: the queue (or other hop) the call went through, when it is not simply the answerer.
  const through = baseExtension(pick(r, 'call-through-user'));
  let via: Party | null = null;
  if (through && through !== term) {
    const name = nameOf(through);
    via = { primary: name || numberText(through), secondary: name ? through : '' };
  }

  const id = pick(r, 'id', 'call-parent-cdr-id', 'call-orig-call-id') || `cdr-${index}`;
  return {
    id,
    cdrId: pick(r, 'call-parent-cdr-id', 'id'),
    startedAt: parseSwitchTime(pick(r, 'call-start-datetime')),
    direction,
    from,
    to,
    via,
    talkSeconds: toInt(r['call-talking-duration-seconds']),
    totalSeconds: toInt(r['call-total-duration-seconds']),
    result: pick(r, 'call-disconnect-reason-text'),
    voicemail: /vmail/i.test(pick(r, 'call-term-to-uri')),
    recorded: recordedFlag(r),
  };
}

/** Directory, queue and park names by extension, kept stable while nothing in them changes. */
function useNames(): ReadonlyMap<string, string> {
  const { contacts, queues, parks } = useSwitchboard();
  const last = useRef<Map<string, string>>(new Map());
  return useMemo(() => {
    const next = new Map<string, string>();
    for (const p of parks) if (p.name) next.set(p.ext, p.name);
    for (const q of queues) next.set(q.ext, q.name);
    for (const c of contacts) if (c.name && c.name !== c.user) next.set(c.user, c.name);
    const prev = last.current;
    if (next.size === prev.size && Array.from(next).every(([k, v]) => prev.get(k) === v)) return prev;
    last.current = next;
    return next;
  }, [contacts, parks, queues]);
}

// ---------------------------------------------------------------------------
// Recordings
// ---------------------------------------------------------------------------

interface RecordingLeg {
  url: string;
  seconds: number | null;
}

interface RecordingResult {
  legs: RecordingLeg[];
  /** The switch's own status word for the recording, when it gave one. */
  status: string;
}

/**
 * A URL safe to hand to <audio> and a link: http(s) only, never
 * `javascript:` or `data:`. vCon URLs get the two parameters Horizon's own
 * player adds before playing them (`convert=signed`, `stereo=force`); any
 * other URL is left exactly as issued, since it may be signed as it stands.
 */
function safeUrl(raw: string, hostParams: boolean): string {
  const s = raw.trim();
  if (!s) return '';
  let u: URL;
  try {
    // Relative to the page, so a root-relative file path from the switch still resolves.
    u = new URL(s, typeof window === 'undefined' ? undefined : window.location.href);
  } catch {
    return '';
  }
  if (u.protocol !== 'https:' && u.protocol !== 'http:') return '';
  if (hostParams) {
    if (!u.searchParams.has('convert')) u.searchParams.set('convert', 'signed');
    if (!u.searchParams.has('stereo')) u.searchParams.set('stereo', 'force');
  }
  return u.toString();
}

function secondsOrNull(v: unknown): number | null {
  const n = toFloat(v);
  return n > 0 ? n : null;
}

function fromVcon(doc: unknown): RecordingResult {
  const dialog = doc && typeof doc === 'object' ? (doc as { dialog?: unknown }).dialog : null;
  const entries = (Array.isArray(dialog) ? dialog : [])
    .filter((d): d is NsRecord => !!d && typeof d === 'object' && lower((d as NsRecord).type) === 'recording')
    .sort((a, b) => (Date.parse(str(a.start)) || 0) - (Date.parse(str(b.start)) || 0));
  const legs: RecordingLeg[] = [];
  let status = '';
  for (const d of entries) {
    const x = d['x-netsapiens'];
    const s = x && typeof x === 'object' ? str((x as NsRecord).recording_status).trim() : '';
    if (s && !status) status = s;
    const url = safeUrl(str(d.url), true);
    if (url) legs.push({ url, seconds: secondsOrNull(d.duration) });
  }
  return { legs, status };
}

function fromRecordingRecords(recs: NsRecord[]): RecordingResult {
  const legs: RecordingLeg[] = [];
  let status = '';
  for (const r of recs) {
    const s = str(r['call-recording-status']).trim();
    if (s && !status) status = s;
    const url = safeUrl(first(r['file-access-url'], r.url, r['recording-url'], r.file_url, r['download-url']), false);
    if (url) legs.push({ url, seconds: secondsOrNull(r['file-duration-seconds']) });
  }
  return { legs, status };
}

/** "202609": the month partition the vCon read takes, from the call's UTC start. */
function yyyymm(ms: number): string {
  const d = new Date(ms);
  return `${d.getUTCFullYear()}${String(d.getUTCMonth() + 1).padStart(2, '0')}`;
}

async function readRecording(api: HorizonApiClient, domain: string, row: HistoryRow): Promise<RecordingResult> {
  if (!row.cdrId) return { legs: [], status: '' };
  const path = `/domains/${encodeURIComponent(domain)}/vcon/${encodeURIComponent(row.cdrId)}`;
  let doc: unknown;
  try {
    doc = await api.get(path, row.startedAt != null ? { yyyymm: yyyymm(row.startedAt) } : undefined);
  } catch (err) {
    if (classifyError(err) !== 'not-found') throw err;
    // No vCon route here: an older switch may still serve the CDR recording route.
    try {
      return fromRecordingRecords(await ns.readCdrRecording(api, domain, row.cdrId));
    } catch (err2) {
      if (classifyError(err2) === 'not-found') return { legs: [], status: '' };
      throw err2;
    }
  }
  return fromVcon(doc);
}

type Playback =
  | { row: HistoryRow; status: 'loading' }
  | { row: HistoryRow; status: 'ready'; legs: RecordingLeg[] }
  | { row: HistoryRow; status: 'none'; switchStatus: string }
  | { row: HistoryRow; status: 'error'; message: string };

// ---------------------------------------------------------------------------
// The section
// ---------------------------------------------------------------------------

interface Loaded {
  status: 'loading' | 'ready' | 'error';
  raw: NsCdr[];
  /** Rows read so far, the next page's offset. */
  fetched: number;
  /** The last page was full, so there may be more. */
  more: boolean;
  error: string | null;
}

const EMPTY_LOAD: Loaded = { status: 'loading', raw: [], fetched: 0, more: false, error: null };

const historyRowId = (r: HistoryRow) => r.id;
const NEWEST_FIRST = { sorting: [{ field: 'startedAt', sort: 'desc' as const }] };

function HistoryBody({ user }: { user: string | null }) {
  const kit = useKit();
  const { Box, Stack, Typography, DatagridTemplate, Alert, Icon } = kit;
  const { api, domain } = useSwitchboard();
  const names = useNames();
  const [range, setRange] = usePersistentState<RangePreset>(
    user ? 'history.range.user' : 'history.range.domain',
    user ? 'week' : 'today',
    isRangePreset,
  );
  const [load, setLoad] = useState<Loaded>(EMPTY_LOAD);
  const [loadingMore, setLoadingMore] = useState(false);
  const [moreError, setMoreError] = useState<string | null>(null);
  const [reloadKey, setReloadKey] = useState(0);
  const [playback, setPlayback] = useState<Playback | null>(null);
  const seq = useRef(0);
  const playSeq = useRef(0);
  const span = useRef<RangeWindow | null>(null);

  // First page: on open, and when the range, domain or refresh changes.
  useEffect(() => {
    const my = ++seq.current;
    const w = resolveRange(range);
    span.current = w;
    playSeq.current += 1;
    setPlayback(null);
    setMoreError(null);
    setLoadingMore(false);
    setLoad(EMPTY_LOAD);
    ns.readCdrs(api, domain, { ...w, user: user ?? undefined, limit: PAGE, offset: 0 })
      .then((raw) => {
        if (my !== seq.current) return;
        setLoad({ status: 'ready', raw, fetched: raw.length, more: raw.length >= PAGE, error: null });
      })
      .catch((err: unknown) => {
        if (my !== seq.current) return;
        setLoad({ status: 'error', raw: [], fetched: 0, more: false, error: describeReadError('call history', err) });
      });
  }, [api, domain, range, reloadKey, user]);

  const reload = useCallback(() => setReloadKey((k) => k + 1), []);

  const loadMore = useCallback(() => {
    const w = span.current;
    if (!w || loadingMore) return;
    const my = seq.current;
    setLoadingMore(true);
    setMoreError(null);
    ns.readCdrs(api, domain, { ...w, user: user ?? undefined, limit: PAGE, offset: load.fetched })
      .then((page) => {
        if (my !== seq.current) return;
        setLoad((prev) => {
          const ids = new Set(prev.raw.map((r) => pick(r, 'id')));
          const fresh = page.filter((r) => {
            const id = pick(r, 'id');
            return !id || !ids.has(id);
          });
          const fetched = prev.fetched + page.length;
          return { ...prev, raw: [...prev.raw, ...fresh], fetched, more: page.length >= PAGE };
        });
      })
      .catch((err: unknown) => {
        if (my === seq.current) setMoreError(describeReadError('more calls', err));
      })
      .finally(() => {
        if (my === seq.current) setLoadingMore(false);
      });
  }, [api, domain, load.fetched, loadingMore, user]);

  const rows = useMemo(() => {
    const seen = new Set<string>();
    return load.raw.map((r, i) => {
      const row = toRow(r, i, names);
      if (seen.has(row.id)) row.id = `${row.id}#${i}`;
      seen.add(row.id);
      return row;
    });
  }, [load.raw, names]);

  const play = useCallback(
    (row: HistoryRow) => {
      const my = ++playSeq.current;
      setPlayback({ row, status: 'loading' });
      readRecording(api, domain, row)
        .then((res) => {
          if (my !== playSeq.current) return;
          setPlayback(
            res.legs.length ? { row, status: 'ready', legs: res.legs } : { row, status: 'none', switchStatus: res.status },
          );
        })
        .catch((err: unknown) => {
          if (my === playSeq.current) setPlayback({ row, status: 'error', message: describeReadError('this recording', err) });
        });
    },
    [api, domain],
  );
  const closePlayback = useCallback(() => {
    playSeq.current += 1;
    setPlayback(null);
  }, []);

  // The player opens above a tall grid, so bring it into view when a row's Play is pressed.
  const panelId = useId();
  const playingId = playback?.row.id ?? null;
  useEffect(() => {
    if (!playingId) return;
    document.getElementById(panelId)?.scrollIntoView?.({ block: 'nearest', behavior: 'smooth' });
  }, [panelId, playingId]);

  const columns = useMemo(() => historyColumns(kit), [kit]);
  const actions = useMemo<DatagridAction<HistoryRow>[]>(
    () => [
      {
        icon: 'lucide:play',
        label: 'Play recording',
        color: 'primary',
        onClick: play,
        visible: (row) => row.recorded,
        getTooltip: (row) => `Play the recording of this call from ${row.from.primary}`,
      },
    ],
    [play],
  );
  const toolbar = useMemo<DatagridToolbarConfig>(
    () => ({
      enableSearch: true,
      searchPlaceholder: 'Search calls',
      enableExport: true,
      exportFilename: user ? `call-history-${user}-${range}` : `call-history-${range}`,
      enableColumns: true,
      enableRefresh: true,
      onRefresh: reload,
      refreshing: load.status === 'loading',
    }),
    [load.status, range, reload, user],
  );

  const capped = load.fetched >= MAX_ROWS;
  const canLoadMore = load.status === 'ready' && load.more && !capped;

  let body: React.ReactNode;
  if (load.status === 'loading') {
    body = (
      <Stack direction="row" alignItems="center" spacing={1} sx={{ py: 4, justifyContent: 'center', color: 'text.secondary' }}>
        <Icon name="svg-spinners:ring-resize" size={20} />
        <Typography variant="body2" color="text.secondary">
          Loading calls...
        </Typography>
      </Stack>
    );
  } else if (load.status === 'error') {
    body = (
      <Alert
        severity="error"
        title="Call history is unavailable"
        message={load.error ?? undefined}
        action={{ label: 'Try again', onClick: reload }}
      />
    );
  } else if (!rows.length) {
    body = <Empty>No calls in this range.</Empty>;
  } else {
    body = (
      <DatagridTemplate
        data={rows}
        columns={columns}
        actions={actions}
        toolbar={toolbar}
        getRowId={historyRowId}
        initialState={NEWEST_FIRST}
        defaultPageSize={25}
        pageSizeOptions={[25, 50, 100]}
        rowHeight={56}
        height="520px"
      />
    );
  }

  return (
    <Stack spacing={1.5}>
      <Stack direction="row" alignItems="center" flexWrap="wrap" sx={{ gap: 1.5 }}>
        <RangeToggle value={range} onChange={setRange} />
        <Box sx={{ flex: 1 }} />
        {load.status === 'ready' && rows.length ? (
          <Typography variant="caption" color="text.secondary">
            {plural(rows.length, 'call')}
            {canLoadMore ? ' so far' : ''}
          </Typography>
        ) : null}
      </Stack>

      {playback ? <RecordingPanel id={panelId} playback={playback} onClose={closePlayback} /> : null}

      {body}

      {load.status === 'ready' && rows.length ? (
        <Stack direction="row" alignItems="center" flexWrap="wrap" sx={{ gap: 1.5 }}>
          {canLoadMore ? (
            <SmallButton icon="lucide:chevron-down" label="Load more" busy={loadingMore} onClick={loadMore} />
          ) : null}
          {capped && load.more ? (
            <Typography variant="caption" color="text.secondary">
              Showing the first {MAX_ROWS.toLocaleString()} calls. Pick a shorter range to see the rest.
            </Typography>
          ) : null}
        </Stack>
      ) : null}
      {moreError ? <Alert severity="warning" message={moreError} onClose={() => setMoreError(null)} /> : null}
    </Stack>
  );
}

// ---------------------------------------------------------------------------
// Grid columns and cells
// ---------------------------------------------------------------------------

function historyColumns(kit: Kit): DatagridColumn<HistoryRow>[] {
  const { Box, Chip, Icon, Stack, Typography } = kit;
  const partyText = (p: Party | null) => (p ? [p.primary, p.secondary].filter(Boolean).join(' ') : '');
  const duration = (field: 'talkSeconds' | 'totalSeconds', headerName: string): DatagridColumn<HistoryRow> => ({
    field,
    headerName,
    type: 'number',
    width: 110,
    valueFormatter: (_v, row) => formatElapsed(row[field]),
    renderCell: ({ row }) => (
      <Typography component="span" variant="body2" sx={{ fontVariantNumeric: 'tabular-nums' }}>
        {formatElapsed(row[field])}
      </Typography>
    ),
  });
  return [
    {
      field: 'startedAt',
      headerName: 'Time',
      width: 190,
      valueGetter: (_v, row) => row.startedAt ?? 0,
      valueFormatter: (_v, row) => formatDateTime(row.startedAt),
      renderCell: ({ row }) => formatDateTime(row.startedAt),
    },
    {
      field: 'direction',
      headerName: 'Direction',
      width: 130,
      valueGetter: (_v, row) => DIRECTION[row.direction].label,
      renderCell: ({ row }) => {
        const d = DIRECTION[row.direction];
        return (
          <Stack direction="row" alignItems="center" spacing={0.75} sx={{ height: '100%' }}>
            <Box sx={{ display: 'flex', color: d.tone === 'neutral' ? 'text.secondary' : toneText(d.tone) }}>
              <Icon name={d.icon} size={16} />
            </Box>
            <Typography component="span" variant="body2">
              {d.label}
            </Typography>
          </Stack>
        );
      },
    },
    {
      field: 'from',
      headerName: 'From',
      flex: 1,
      minWidth: 180,
      valueGetter: (_v, row) => partyText(row.from),
      renderCell: ({ row }) => twoLine(kit, row.from.primary, row.from.secondary),
    },
    {
      field: 'to',
      headerName: 'To',
      flex: 1,
      minWidth: 180,
      valueGetter: (_v, row) => partyText(row.to),
      renderCell: ({ row }) => twoLine(kit, row.to.primary, row.to.secondary),
    },
    {
      field: 'via',
      headerName: 'Via',
      width: 160,
      valueGetter: (_v, row) => partyText(row.via),
      renderCell: ({ row }) => (row.via ? twoLine(kit, row.via.primary, row.via.secondary) : EMPTY_CELL),
    },
    duration('talkSeconds', 'Talk time'),
    duration('totalSeconds', 'Total'),
    {
      field: 'result',
      headerName: 'Result',
      width: 170,
      valueGetter: (_v, row) => [row.result, row.voicemail ? 'Went to voicemail' : ''].filter(Boolean).join('; '),
      renderCell: ({ row }) => twoLine(kit, row.result || EMPTY_CELL, row.voicemail ? 'Went to voicemail' : ''),
    },
    {
      field: 'recording',
      headerName: 'Recording',
      width: 125,
      valueGetter: (_v, row) => (row.recorded ? 'Recorded' : ''),
      renderCell: ({ row }) =>
        row.recorded ? (
          <Chip size="small" color="info" variant="outlined" label="Recorded" icon={<Icon name="lucide:disc-3" size={14} />} />
        ) : (
          EMPTY_CELL
        ),
    },
  ];
}

function twoLine(kit: Kit, primary: React.ReactNode, secondary: React.ReactNode) {
  const { Stack, Typography } = kit;
  return (
    <Stack justifyContent="center" sx={{ minWidth: 0, height: '100%', lineHeight: 1.25 }}>
      <Typography variant="body2" noWrap sx={{ fontWeight: 500 }}>
        {primary}
      </Typography>
      {secondary ? (
        <Typography variant="caption" color="text.secondary" noWrap sx={{ fontVariantNumeric: 'tabular-nums' }}>
          {secondary}
        </Typography>
      ) : null}
    </Stack>
  );
}

function RecordingPanel({ id, playback, onClose }: { id: string; playback: Playback; onClose: () => void }) {
  const { Box, Button, Icon, Paper, Stack, Typography, Alert } = useKit();
  const { row } = playback;
  const summary = `${row.from.primary} to ${row.to.primary}, ${formatDateTime(row.startedAt)}`;
  return (
    <Paper id={id} variant="outlined" sx={{ p: 2, scrollMarginTop: 16 }} aria-label="Call recording">
      <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: 1.5, minWidth: 0 }}>
        <Box sx={{ color: 'primary.main', display: 'flex' }}>
          <Icon name="lucide:audio-lines" size={18} />
        </Box>
        <Typography variant="subtitle2" sx={{ fontWeight: 700, flexShrink: 0 }}>
          Recording
        </Typography>
        <Typography variant="caption" color="text.secondary" noWrap sx={{ minWidth: 0 }} title={summary}>
          {summary}
        </Typography>
        <Box sx={{ flex: 1 }} />
        <ActionIcon icon="lucide:x" label="Close the recording" onClick={onClose} />
      </Stack>

      {playback.status === 'loading' ? (
        <Stack direction="row" alignItems="center" spacing={1} sx={{ color: 'text.secondary' }}>
          <Icon name="svg-spinners:ring-resize" size={18} />
          <Typography variant="body2" color="text.secondary">
            Loading the recording...
          </Typography>
        </Stack>
      ) : null}

      {playback.status === 'none' ? (
        <Empty>
          No recording file is available for this call.
          {playback.switchStatus ? ` The phone system reports its recording status as "${playback.switchStatus}".` : ''}
        </Empty>
      ) : null}

      {playback.status === 'error' ? <Alert severity="error" message={playback.message} /> : null}

      {playback.status === 'ready'
        ? playback.legs.map((leg, i) => (
            <Stack key={`${i}:${leg.url}`} spacing={1} sx={{ mt: i ? 2 : 0 }}>
              {playback.legs.length > 1 ? (
                <Typography variant="caption" color="text.secondary">
                  Leg {i + 1}
                  {leg.seconds ? `, ${formatElapsed(leg.seconds)}` : ''}
                </Typography>
              ) : null}
              <Box sx={{ '& audio': { width: '100%', display: 'block' } }}>
                <audio controls preload="none" src={leg.url} aria-label={`Recording of the call from ${row.from.primary}`} />
              </Box>
              <Box>
                <Button
                  size="small"
                  variant="text"
                  href={leg.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  startIcon={<Icon name="lucide:external-link" size={16} />}
                  sx={{ textTransform: 'none', fontWeight: 600 }}
                >
                  Open recording
                </Button>
              </Box>
            </Stack>
          ))
        : null}
    </Paper>
  );
}
