/**
 * "Staff {queue}" (the Engage QueueStaffingDialog): everyone in the directory
 * against one queue, members first, with Member / Taking calls / Max calls,
 * and a banner that brings dormant members on in one click.
 */
import { useEffect, useMemo, useState } from 'react';

import type { QueueMember } from '../types';
import { useSwitchboard } from '../data/SwitchboardData';
import * as ns from '../api/ns';
import { agentId, memberLoggedIn } from '../model/agents';
import { useKit } from '../ui/kit';
import { Pill, SmallButton } from '../ui/bits';
import { MemberControls, RowError, useRowRunner } from './membership';

interface Person {
  user: string;
  name: string;
  hint: string;
  member: QueueMember | null;
}

export function QueueStaffingPanel({ queue, onClose }: { queue: string | null; onClose: () => void }) {
  const { SidePanel, Stack, Typography, Alert, SearchField, Paper, Box, Button, Icon } = useKit();
  const sb = useSwitchboard();
  const { queues, contacts, caps, domain, api, reloadRoster } = sb;
  const q = queues.find((x) => x.ext === queue) ?? null;
  const [query, setQuery] = useState('');
  const { pendingRow, bulk, busy, rowErrors, runRow, runBulk } = useRowRunner();
  const canManage = caps.manageQueueAgents;

  // A fresh roster every time the panel opens.
  useEffect(() => {
    if (queue) {
      setQuery('');
      void reloadRoster(queue);
    }
  }, [queue, reloadRoster]);

  const people = useMemo<Person[]>(() => {
    if (!q) return [];
    const roster = q.roster ?? [];
    const byUser = new Map(roster.map((m) => [m.user, m] as const));
    const list: Person[] = contacts
      .filter((c) => /^\d+$/.test(c.user))
      .map((c) => ({
        user: c.user,
        name: c.name,
        hint: [c.site, c.department].filter(Boolean).join(' - '),
        member: byUser.get(c.user) ?? null,
      }));
    const seen = new Set(list.map((p) => p.user));
    for (const m of roster) {
      if (!seen.has(m.user)) list.push({ user: m.user, name: m.name || m.user, hint: '', member: m });
    }
    return list.sort((a, b) => {
      if (!!a.member !== !!b.member) return a.member ? -1 : 1;
      return a.name.localeCompare(b.name) || a.user.localeCompare(b.user, undefined, { numeric: true });
    });
  }, [contacts, q]);

  const needle = query.trim().toLowerCase();
  const shown = people.filter((p) => !needle || p.name.toLowerCase().includes(needle) || p.user.includes(needle));
  const members = people.filter((p) => p.member);
  const staffed = members.filter((p) => p.member && memberLoggedIn(p.member)).length;
  const dormant = members.filter((p) => p.member && !memberLoggedIn(p.member));
  const waiting = q ? q.waiting.filter((c) => !c.placeholder).length || q.reportedWaiting : 0;

  const after = async () => {
    if (queue) await reloadRoster(queue);
  };
  const aid = (user: string) => agentId(user, domain);

  const setMember = (p: Person, on: boolean) =>
    runRow(
      p.user,
      () => (on ? ns.addAgent(api, domain, queue!, aid(p.user)) : ns.removeAgent(api, domain, queue!, aid(p.user))),
      after,
    );
  const setTaking = (p: Person, on: boolean) => runRow(p.user, () => ns.setTakingCalls(api, domain, queue!, aid(p.user), on), after);
  const setMax = (p: Person, n: number) => runRow(p.user, () => ns.setCallLimit(api, domain, queue!, aid(p.user), n), after);
  const bringOn = () =>
    runBulk(
      dormant.map((p) => ({ row: p.user, fn: () => ns.setTakingCalls(api, domain, queue!, aid(p.user), true) })),
      after,
    );

  const title = q ? `Staff ${q.name}` : 'Staff queue';
  const description = q
    ? `${staffed} of ${members.length} agent${members.length === 1 ? '' : 's'} taking calls${
        waiting > 0 ? `, ${waiting} caller${waiting === 1 ? '' : 's'} waiting` : ''
      }. Membership is the setup; the Taking calls switch is what you change during a spike.`
    : '';

  return (
    <SidePanel
      open={queue !== null}
      onClose={onClose}
      title={title}
      subtitle={q ? `Queue ${q.ext}` : undefined}
      icon={<Icon name="lucide:user-plus" size={20} />}
      width="lg"
      footer={
        <Stack direction="row" justifyContent="flex-end" sx={{ width: '100%' }}>
          <Button variant="contained" onClick={onClose}>
            Done
          </Button>
        </Stack>
      }
    >
      {!q ? (
        <Typography color="text.secondary">That queue is no longer in this domain.</Typography>
      ) : (
        <Stack spacing={2}>
          <Typography variant="body2" color="text.secondary">
            {description}
          </Typography>
          {!canManage ? (
            <Alert severity="info">Your scope can view this queue's staffing but not change it.</Alert>
          ) : null}
          {canManage && dormant.length ? (
            <Alert severity="warning">
              <Stack direction="row" spacing={2} alignItems="center" justifyContent="space-between">
                <span>
                  {dormant.length === 1
                    ? `${dormant[0].name} is an agent here but is not taking calls.`
                    : `${dormant.length} agents are on this queue but are not taking calls.`}
                </span>
                <SmallButton
                  icon="lucide:zap"
                  label={dormant.length === 1 ? 'Bring them on' : 'Bring them all on'}
                  variant="contained"
                  color="warning"
                  busy={bulk}
                  disabled={busy}
                  onClick={() => void bringOn()}
                />
              </Stack>
            </Alert>
          ) : null}
          <SearchField value={query} onChange={setQuery} onClear={() => setQuery('')} placeholder="Search people by name or extension" fullWidth size="small" />
          {q.rosterError ? <Alert severity="error">{q.rosterError}</Alert> : null}
          {!q.roster ? (
            <Typography variant="body2" color="text.secondary">
              Loading this queue's agents...
            </Typography>
          ) : shown.length === 0 ? (
            <Typography variant="body2" color="text.secondary">
              {needle ? `Nobody matches "${query.trim()}".` : 'No people found.'}
            </Typography>
          ) : (
            <Stack spacing={1}>
              {shown.map((p) => {
                const m = p.member;
                const loggedIn = m ? memberLoggedIn(m) : false;
                const sub = m ? (loggedIn ? 'Taking calls from this queue' : 'Agent here, not taking calls') : p.hint || 'Not an agent on this queue';
                return (
                  <Paper key={p.user} variant="outlined" sx={{ p: 1.25 }}>
                    <Stack direction="row" spacing={1} alignItems="center">
                      <Box sx={{ flex: 1, minWidth: 0 }}>
                        <Typography variant="body2" sx={{ fontWeight: 700 }} noWrap>
                          {p.name}{' '}
                          <Box component="span" sx={{ color: 'text.secondary', fontWeight: 400 }}>
                            {p.user}
                          </Box>
                        </Typography>
                        <Typography variant="caption" color="text.secondary">
                          {sub}
                        </Typography>
                        <RowError message={rowErrors[p.user]} />
                      </Box>
                      {m && m.status === 'on-call' ? <Pill tone="info" outlined label="On a call" /> : null}
                    </Stack>
                    <Box sx={{ mt: 0.75 }}>
                      <MemberControls
                        state={{ member: !!m, loggedIn, maxCalls: m?.callLimit }}
                        disabled={!canManage || busy}
                        pending={pendingRow === p.user}
                        names={{
                          member: `${m ? 'Remove' : 'Add'} ${p.name} ${m ? 'from' : 'to'} ${q.name}`,
                          taking: `${loggedIn ? 'Stop' : 'Start'} ${p.name} taking calls from ${q.name}`,
                          max: `Max simultaneous calls for ${p.name} from ${q.name}`,
                        }}
                        onMember={(on) => void setMember(p, on)}
                        onTaking={(on) => void setTaking(p, on)}
                        onMaxCalls={(n) => void setMax(p, n)}
                      />
                    </Box>
                  </Paper>
                );
              })}
            </Stack>
          )}
        </Stack>
      )}
    </SidePanel>
  );
}
