/**
 * Real-Time mode (the Engage "board"): the filter toolbar, then three panels
 *   Contacts (n)      directory grouped by site and department bands
 *   Call Queues (n)   pinned queues, then queues grouped the same way
 *   Auto Attendants   the domain's auto attendants
 * Site and Department filters also scope the park rail and the wallboard.
 */
import type * as React from 'react';
import { useCallback, useEffect, useMemo, useState } from 'react';

import type { Contact, QueueMember, QueueView } from '../../types';
import { useSwitchboard, useWant } from '../../data/SwitchboardData';
import { isStringArray, oneOf, usePersistentState } from '../../data/persist';
import { toQueueMember } from '../../model/agents';
import {
  ALL,
  CONTACT_SORTS,
  QUEUE_SORTS,
  collectFilterValues,
  filterContacts,
  filterQueues,
  groupBySiteAndDept,
  reconcileSelection,
  sortContacts,
  sortQueues,
} from '../../model/directory';
import type { Band, ContactSort, QueueSort } from '../../model/directory';
import { useKit } from '../../ui/kit';
import { Empty, Pill } from '../../ui/bits';
import { ContactCard } from './ContactCard';
import { QueueTile } from './QueueTile';

type RtTab = 'contacts' | 'queues' | 'attendants';

export function RealTimeView() {
  const { Stack, Tabs, SearchField, Select, Box } = useKit();
  const sb = useSwitchboard();
  const { contacts, queues, parks, loading } = sb;

  const [tab, setTab] = usePersistentState<RtTab>('rt.tab', 'contacts', oneOf<RtTab>('contacts', 'queues', 'attendants'));
  const [site, setSite] = usePersistentState<string>('rt.site', ALL);
  const [dept, setDept] = usePersistentState<string>('rt.dept', ALL);
  const [contactSort, setContactSort] = usePersistentState<ContactSort>(
    'rt.contactSort',
    'online',
    oneOf<ContactSort>('online', 'firstname', 'lastname', 'extension'),
  );
  const [queueSort, setQueueSort] = usePersistentState<QueueSort>('rt.queueSort', 'name', oneOf<QueueSort>('name', 'extension', 'agents'));
  const [pinned, setPinned] = usePersistentState<string[]>('rt.pinned', [], isStringArray);
  const [contactQuery, setContactQuery] = useState('');
  const [queueQuery, setQueueQuery] = useState('');
  const [collapsed, setCollapsed] = useState<Set<string>>(() => new Set());

  const { sites, departments } = useMemo(() => collectFilterValues(contacts, queues, parks), [contacts, parks, queues]);

  // A stored filter value that no longer exists falls back to All once loaded.
  useEffect(() => {
    if (loading) return;
    const s = reconcileSelection(site, sites);
    if (s !== site) setSite(s);
    const d = reconcileSelection(dept, departments);
    if (d !== dept) setDept(d);
  }, [departments, dept, loading, setDept, setSite, site, sites]);

  const shownContacts = useMemo(
    () => sortContacts(filterContacts(contacts, contactQuery, site, dept), contactSort),
    [contactQuery, contactSort, contacts, dept, site],
  );
  const shownQueues = useMemo(
    () => sortQueues(filterQueues(queues, queueQuery, site, dept), queueSort),
    [dept, queueQuery, queueSort, queues, site],
  );

  const toggle = useCallback((key: string) => {
    setCollapsed((prev) => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  }, []);

  // Horizon's Select sizes itself wider than MUI's default; a fixed-width box
  // keeps the toolbar on one line in the space left beside the operator rail.
  const filterSelect = (label: string, value: string, values: string[], onChange: (v: string) => void) => (
    <Box sx={{ width: 150 }}>
      <Select
        size="small"
        fullWidth
        label={label}
        value={value}
        onChange={(e: React.ChangeEvent<HTMLInputElement>) => onChange(String(e.target.value))}
        options={[{ value: ALL, label: 'All' }, ...values.map((v) => ({ value: v, label: v }))]}
      />
    </Box>
  );

  return (
    <Stack spacing={1.5}>
      {tab !== 'attendants' ? (
        <Stack direction="row" spacing={1.5} alignItems="center" flexWrap="wrap" useFlexGap>
          {tab === 'contacts' ? (
            <>
              <Box sx={{ width: 210 }}>
                <SearchField
                  size="small"
                  fullWidth
                  value={contactQuery}
                  onChange={setContactQuery}
                  onClear={() => setContactQuery('')}
                  placeholder="Search contacts..."
                />
              </Box>
              {filterSelect('Site', site, sites, setSite)}
              {filterSelect('Department', dept, departments, setDept)}
              <Box sx={{ flex: 1 }} />
              <Box sx={{ width: 140 }}>
                <Select
                  size="small"
                  fullWidth
                  label="Sort by"
                  value={contactSort}
                  onChange={(e: React.ChangeEvent<HTMLInputElement>) => setContactSort(String(e.target.value) as ContactSort)}
                  options={CONTACT_SORTS}
                />
              </Box>
            </>
          ) : (
            <>
              <Box sx={{ width: 240 }}>
                <SearchField
                  size="small"
                  fullWidth
                  value={queueQuery}
                  onChange={setQueueQuery}
                  onClear={() => setQueueQuery('')}
                  placeholder="Search queues..."
                />
              </Box>
              {site !== ALL || dept !== ALL ? (
                <Pill
                  tone="primary"
                  outlined
                  label={`Filtered: ${[site !== ALL ? site : '', dept !== ALL ? dept : ''].filter(Boolean).join(' · ')}`}
                  title="Site and Department filters from the Contacts tab also apply to queues"
                />
              ) : null}
              <Box sx={{ flex: 1 }} />
              <Box sx={{ width: 170 }}>
                <Select
                  size="small"
                  fullWidth
                  label="Sort by"
                  value={queueSort}
                  onChange={(e: React.ChangeEvent<HTMLInputElement>) => setQueueSort(String(e.target.value) as QueueSort)}
                  options={QUEUE_SORTS}
                />
              </Box>
            </>
          )}
        </Stack>
      ) : null}

      <Tabs
        variant="standard"
        value={tab}
        onChange={(v) => setTab(v === 'queues' ? 'queues' : v === 'attendants' ? 'attendants' : 'contacts')}
        options={[
          { value: 'contacts', label: `Contacts (${shownContacts.length})`, icon: 'lucide:users' },
          { value: 'queues', label: `Call Queues (${shownQueues.length})`, icon: 'lucide:list-ordered' },
          { value: 'attendants', label: 'Auto Attendants', icon: 'lucide:bot-message-square' },
        ]}
      />

      {tab === 'contacts' ? (
        <ContactsPanel contacts={shownContacts} collapsed={collapsed} onToggle={toggle} loading={loading} />
      ) : null}
      {tab === 'queues' ? (
        <QueuesPanel
          queues={shownQueues}
          all={queues}
          pinned={pinned}
          onTogglePin={(ext) => setPinned((p) => (p.includes(ext) ? p.filter((x) => x !== ext) : [...p, ext]))}
          collapsed={collapsed}
          onToggle={toggle}
        />
      ) : null}
      {tab === 'attendants' ? <AutoAttendantsPanel /> : null}
    </Stack>
  );
}

// ---------------------------------------------------------------------------
// Bands
// ---------------------------------------------------------------------------

function SiteBand<T>({
  band,
  kind,
  collapsed,
  onToggle,
  keyPrefix,
  render,
}: {
  band: Band<T>;
  kind: 'contact' | 'queue';
  collapsed: Set<string>;
  onToggle: (key: string) => void;
  keyPrefix: string;
  render: (item: T) => React.ReactNode;
}) {
  const { Box, Stack, Typography, Icon, Paper } = useKit();
  const siteKey = `${keyPrefix}${band.site}`;
  const open = !collapsed.has(siteKey);
  const noun = kind === 'contact' ? 'contact' : 'queue';
  return (
    <Paper variant="outlined" sx={{ overflow: 'hidden' }}>
      <Box
        component="button"
        type="button"
        onClick={() => onToggle(siteKey)}
        aria-expanded={open}
        title={`Site: ${band.site} (${band.count} ${noun}${band.count === 1 ? '' : 's'}). Click to ${open ? 'collapse' : 'expand'}.`}
        sx={{
          all: 'unset',
          boxSizing: 'border-box',
          width: '100%',
          cursor: 'pointer',
          display: 'flex',
          alignItems: 'center',
          gap: 1,
          px: 2,
          py: 1.1,
          bgcolor: 'action.selected',
          '&:hover': { bgcolor: 'action.focus' },
          '&:focus-visible': { outline: '2px solid', outlineColor: 'primary.main' },
        }}
      >
        <Icon name={open ? 'lucide:chevron-down' : 'lucide:chevron-right'} size={16} />
        <Typography variant="subtitle2" sx={{ fontWeight: 700, flex: 1 }}>
          {band.site}
        </Typography>
        <Pill label={band.count} />
      </Box>
      {open ? (
        <Stack>
          {band.departments.map((d) => {
            const deptKey = `${siteKey}:${d.department}`;
            const deptOpen = !collapsed.has(deptKey);
            return (
              <Box key={d.department}>
                <Box
                  component="button"
                  type="button"
                  onClick={() => onToggle(deptKey)}
                  aria-expanded={deptOpen}
                  title={`Department: ${d.department} (${d.items.length} ${noun}${d.items.length === 1 ? '' : 's'}). Click to ${deptOpen ? 'collapse' : 'expand'}.`}
                  sx={{
                    all: 'unset',
                    boxSizing: 'border-box',
                    width: '100%',
                    cursor: 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    gap: 1,
                    px: 2,
                    py: 0.75,
                    borderTop: 1,
                    borderColor: 'divider',
                    bgcolor: 'action.hover',
                    '&:hover': { bgcolor: 'action.selected' },
                    '&:focus-visible': { outline: '2px solid', outlineColor: 'primary.main' },
                  }}
                >
                  <Icon name={deptOpen ? 'lucide:chevron-down' : 'lucide:chevron-right'} size={14} />
                  <Typography variant="caption" sx={{ fontWeight: 700, flex: 1 }}>
                    {d.department}
                  </Typography>
                  <Pill label={d.items.length} />
                </Box>
                {deptOpen ? (
                  <Box sx={{ p: 2, display: 'flex', flexWrap: 'wrap', gap: 1.5, alignItems: 'flex-start' }}>
                    {d.items.map((it) => render(it))}
                  </Box>
                ) : null}
              </Box>
            );
          })}
        </Stack>
      ) : null}
    </Paper>
  );
}

// ---------------------------------------------------------------------------
// Contacts
// ---------------------------------------------------------------------------

function ContactsPanel({
  contacts,
  collapsed,
  onToggle,
  loading,
}: {
  contacts: Contact[];
  collapsed: Set<string>;
  onToggle: (key: string) => void;
  loading: boolean;
}) {
  const { Stack } = useKit();
  const { queues, domainAgents, contactsByUser } = useSwitchboard();
  useWant('vm');

  // Queue memberships per person: loaded rosters, else the domain agent row.
  const memberships = useMemo(() => {
    const m = new Map<string, QueueMember[]>();
    for (const q of queues) {
      for (const r of q.roster ?? []) {
        const list = m.get(r.user) ?? [];
        list.push(r);
        m.set(r.user, list);
      }
    }
    for (const a of domainAgents) {
      const member = toQueueMember(a, String(a.callqueue ?? ''));
      if (!member.user || m.has(member.user)) continue;
      const list = String(a.queue_list ?? a.callqueue ?? '')
        .split(',')
        .map((s) => s.trim())
        .filter(Boolean)
        .map((q) => ({ ...member, queue: q, name: contactsByUser.get(member.user)?.name ?? member.name }));
      m.set(member.user, list);
    }
    return m;
  }, [contactsByUser, domainAgents, queues]);

  const bands = useMemo(() => groupBySiteAndDept(contacts, (c) => c.site, (c) => c.department), [contacts]);

  if (!contacts.length) return <Empty>{loading ? 'Loading contacts...' : 'No contacts found'}</Empty>;
  return (
    <Stack spacing={1.5}>
      {bands.map((b) => (
        <SiteBand
          key={b.site}
          band={b}
          kind="contact"
          keyPrefix="contacts:"
          collapsed={collapsed}
          onToggle={onToggle}
          render={(c: Contact) => <ContactCard key={c.user} contact={c} memberships={memberships.get(c.user) ?? []} />}
        />
      ))}
    </Stack>
  );
}

// ---------------------------------------------------------------------------
// Queues
// ---------------------------------------------------------------------------

function QueuesPanel({
  queues,
  all,
  pinned,
  onTogglePin,
  collapsed,
  onToggle,
}: {
  queues: QueueView[];
  all: QueueView[];
  pinned: string[];
  onTogglePin: (ext: string) => void;
  collapsed: Set<string>;
  onToggle: (key: string) => void;
}) {
  const { Stack, Box, Typography, Icon, Paper } = useKit();
  const { errors } = useSwitchboard();
  const pinnedQueues = queues.filter((q) => pinned.includes(q.ext));
  const bands = useMemo(() => groupBySiteAndDept(queues, (q) => q.site, (q) => q.department), [queues]);

  if (!queues.length) {
    if (!all.length && errors.queues) return <Empty>{errors.queues}</Empty>;
    return <Empty>No queues found</Empty>;
  }
  return (
    <Stack spacing={1.5}>
      {pinnedQueues.length ? (
        <Paper variant="outlined" sx={{ overflow: 'hidden', borderColor: 'warning.main' }}>
          <Stack direction="row" alignItems="center" spacing={1} sx={{ px: 2, py: 1.1, bgcolor: 'warning.main', color: 'warning.contrastText' }}>
            <Icon name="lucide:star" size={16} />
            <Typography variant="subtitle2" sx={{ fontWeight: 800, flex: 1 }}>
              PINNED
            </Typography>
            <Typography variant="caption" sx={{ fontWeight: 700 }}>
              {pinnedQueues.length}
            </Typography>
          </Stack>
          <Box sx={{ p: 2, display: 'flex', flexWrap: 'wrap', gap: 1.5 }}>
            {pinnedQueues.map((q) => (
              <QueueTile key={`pinned-${q.ext}`} queue={q} pinned onTogglePin={() => onTogglePin(q.ext)} />
            ))}
          </Box>
        </Paper>
      ) : null}
      {bands.map((b) => (
        <SiteBand
          key={b.site}
          band={b}
          kind="queue"
          keyPrefix=""
          collapsed={collapsed}
          onToggle={onToggle}
          render={(q: QueueView) => (
            <QueueTile key={q.ext} queue={q} pinned={pinned.includes(q.ext)} onTogglePin={() => onTogglePin(q.ext)} />
          )}
        />
      ))}
    </Stack>
  );
}

// ---------------------------------------------------------------------------
// Auto attendants
// ---------------------------------------------------------------------------

function AutoAttendantsPanel() {
  const { Stack, Box, SearchField, Select, Typography, Avatar, Paper, Icon } = useKit();
  const { autoAttendants, errors } = useSwitchboard();
  useWant('aas');
  const [query, setQuery] = useState('');
  const [sort, setSort] = usePersistentState<'name' | 'extension'>('rt.aaSort', 'name', oneOf('name', 'extension'));

  const list = useMemo(() => {
    const q = query.trim().toLowerCase();
    const rows = (autoAttendants ?? []).filter(
      (a) => !q || a.name.toLowerCase().includes(q) || a.ext.toLowerCase().includes(q) || a.id.toLowerCase().includes(q),
    );
    return rows.sort((a, b) =>
      sort === 'extension' ? a.ext.localeCompare(b.ext, undefined, { numeric: true }) : a.displayName.localeCompare(b.displayName),
    );
  }, [autoAttendants, query, sort]);

  const total = autoAttendants?.length ?? 0;
  return (
    <Stack spacing={1.5}>
      <Stack direction="row" spacing={1.5} alignItems="center">
        <Box sx={{ width: 280 }}>
          <SearchField size="small" fullWidth value={query} onChange={setQuery} onClear={() => setQuery('')} placeholder="Search auto attendants..." />
        </Box>
        <Select
          size="small"
          label="Sort"
          value={sort}
          onChange={(e: React.ChangeEvent<HTMLInputElement>) => setSort(e.target.value === 'extension' ? 'extension' : 'name')}
          options={[
            { value: 'name', label: 'Name' },
            { value: 'extension', label: 'Extension' },
          ]}
          sx={{ minWidth: 140 }}
        />
      </Stack>
      {autoAttendants === null ? (
        <Empty>{errors.aas ? 'Failed to load auto attendants. Please try again.' : 'Loading auto attendants...'}</Empty>
      ) : total === 0 ? (
        <Empty>No auto attendants configured</Empty>
      ) : (
        <>
          <Typography variant="caption" color="text.secondary">
            {list.length} of {total} auto attendant{total === 1 ? '' : 's'}
          </Typography>
          {list.length === 0 ? (
            <Empty>No auto attendants match your search</Empty>
          ) : (
            <Box sx={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))', gap: 1.5 }}>
              {list.map((a) => (
                <Paper key={a.id} variant="outlined" sx={{ p: 1.5 }}>
                  <Stack direction="row" spacing={1.5} alignItems="center">
                    <Avatar sx={{ bgcolor: 'action.selected', color: 'primary.main', width: 36, height: 36 }}>
                      <Icon name="lucide:bot-message-square" size={18} />
                    </Avatar>
                    <Box sx={{ minWidth: 0 }}>
                      <Typography variant="body2" sx={{ fontWeight: 700 }} noWrap title={a.displayName}>
                        {a.displayName}
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        <Box component="span" sx={{ fontFamily: 'monospace' }}>
                          Ext. {a.ext}
                        </Box>
                        {a.optionCount > 0 ? ` · ${a.optionCount} option${a.optionCount === 1 ? '' : 's'}` : ''}
                      </Typography>
                    </Box>
                  </Stack>
                </Paper>
              ))}
            </Box>
          )}
        </>
      )}
    </Stack>
  );
}
