/**
 * One of the operator's own calls (the "My Calls" rail).
 *
 * States and copy follow the Engage CallCards: Ringing / Dialing / Connected /
 * On Hold, peer name and number, a running timer, and the CRM link for
 * inbound calls. Controls:
 *   ringing    Answer, Decline (and Hang up on the operator's own outbound call)
 *   connected  Hold / Resume, Transfer, Park, Hang up
 *
 * Answer, hold and transfer are PATCH verbs in the NetSapiens reference; the
 * switch takes them as PUT, which the Horizon proxy carries (see api/ns.ts).
 * Park is a transfer to the park slot, the way the legacy console parks. Every
 * one of them is confirmed by reading the call back, so a click the switch
 * accepted but did not act on is reported as exactly that.
 *
 * Mute, record and send-digits are gone: the v46 switch answers 405 to those
 * routes in every verb, so the buttons could only ever fail. Use the phone or
 * the Horizon softphone for them.
 */
import type * as React from 'react';
import { useMemo, useState } from 'react';

import type { Line, ParkSlot } from '../../types';
import { useSwitchboard } from '../../data/SwitchboardData';
import { useActions } from '../../data/actions';
import { oneOf, usePersistentState } from '../../data/persist';
import * as ns from '../../api/ns';
import { ALL, detectParkTopology, visibleParks } from '../../model/directory';
import { formatPhone } from '../../model/format';
import { useKit } from '../../ui/kit';
import { Pill, SmallButton, Timer, tint } from '../../ui/bits';
import type { Tone } from '../../ui/bits';

const STATE: Record<Line['status'], { label: string; tone: Tone }> = {
  ringing: { label: 'Ringing', tone: 'info' },
  dialing: { label: 'Dialing', tone: 'info' },
  active: { label: 'Connected', tone: 'success' },
  held: { label: 'On Hold', tone: 'warning' },
  unknown: { label: 'Active', tone: 'info' },
};

function crmUrl(template: string, vars: Record<string, string>): string {
  let url = template;
  for (const [k, v] of Object.entries(vars)) url = url.split(`{${k}}`).join(encodeURIComponent(v));
  return /^https?:\/\//i.test(url) ? url : '';
}

function slotLabel(p: ParkSlot): string {
  return p.name && p.name !== p.ext ? `${p.ext} · ${p.name}` : p.ext;
}

function isFree(p: ParkSlot): boolean {
  return p.calls.length === 0 && p.reportedCount === 0;
}

/** What a typed destination becomes: digits and dial characters only. */
function dialable(s: string): string {
  return s.trim().replace(/[\s().-]/g, '');
}

interface Target {
  ext: string;
  label: string;
  kind: 'person' | 'queue' | 'number';
}

export function ActiveCallCard({ line, dynamicPark }: { line: Line; dynamicPark: boolean }) {
  const { Paper, Stack, Typography, Box, Icon, TextField } = useKit();
  const sb = useSwitchboard();
  const { run, isPending } = useActions();
  const { domain, operator, parks, config, api, contacts, queues } = sb;
  const [panel, setPanel] = useState<'none' | 'park' | 'transfer'>('none');
  const [query, setQuery] = useState('');

  const [scope] = usePersistentState<'site' | 'all'>('rail.parkScope', 'site', oneOf('site', 'all'));
  const [site] = usePersistentState<string>('rt.site', ALL);
  const shownParks = useMemo(() => {
    const topology = detectParkTopology(parks);
    return visibleParks(parks, topology, topology === 'domain' ? 'all' : scope, site);
  }, [parks, scope, site]);

  const ref: ns.CallRef = { ids: line.call.controlIds, sessionId: line.call.sessionId };
  const key = line.call.key;
  const ringing = line.status === 'ringing' || line.status === 'dialing';
  const connected = line.status === 'active' || line.status === 'held';
  const held = line.status === 'held';
  const st = STATE[line.status];
  const number = formatPhone(line.peerNumber);
  const name = line.peerName && line.peerName !== line.peerNumber ? line.peerName : number || line.peerNumber || 'Unknown';
  const inbound = line.direction === 'inbound';
  const link =
    inbound && config.crmLinkTemplate
      ? crmUrl(config.crmLinkTemplate, {
          FromCallerID: line.peerNumber,
          FromCallerName: line.call.origName,
          DNIS: line.call.dialed || operator.ext,
          Extension: operator.ext,
        })
      : '';

  const after = () => sb.refresh(['calls', 'queues', 'queued', 'parks']);

  const hangUp = () =>
    run(`hangup:${key}`, () => ns.hangUp(api, domain, operator.ext, ref.ids), {
      success: 'Call disconnected',
      failure: 'Unable to disconnect the call.',
    }).then(after);

  const decline = () =>
    run(`decline:${key}`, () => ns.decline(api, domain, operator.ext, ref.ids), {
      success: 'Call declined',
      failure: 'Unable to decline the call.',
    }).then(after);

  const answer = () =>
    run(
      `answer:${key}`,
      () => ns.answerCall(api, domain, operator.ext, ref, line.call.termUri || `sip:${operator.ext}@${domain}`),
      { success: 'Call answered', failure: 'Unable to answer the call.' },
    ).then(after);

  const toggleHold = () =>
    run(`hold:${key}`, () => ns.setHold(api, domain, operator.ext, ref, !held), {
      success: held ? 'Call resumed' : 'Call on hold',
      failure: held ? 'Unable to resume the call.' : 'Unable to put the call on hold.',
    }).then(after);

  const parkIn = (slot: string) => {
    setPanel('none');
    return run(`park:${key}`, () => ns.parkCall(api, domain, operator.ext, ref, slot), {
      success: `Call parked in ${slot}`,
      failure: `Unable to park the call in ${slot}.`,
    }).then(after);
  };

  const onPark = () => {
    if (!dynamicPark) {
      setPanel((p) => (p === 'park' ? 'none' : 'park'));
      return;
    }
    // Dynamic park: the first free slot the operator can see, named in the toast.
    const free = shownParks.find(isFree) ?? parks.find(isFree);
    if (free) void parkIn(free.ext);
    else setPanel('park');
  };

  const transferTo = (t: Target) => {
    setPanel('none');
    setQuery('');
    return run(`transfer:${key}`, () => ns.transferCall(api, domain, operator.ext, ref, t.ext), {
      success: `Call transferred to ${t.label}`,
      failure: `Unable to transfer the call to ${t.label}.`,
    }).then(after);
  };

  const suggestions = useMemo<Target[]>(() => {
    const q = query.trim().toLowerCase();
    const out: Target[] = [];
    const typed = dialable(query);
    if (/^\+?[0-9*#]{2,}$/.test(typed)) out.push({ ext: typed, label: formatPhone(typed) || typed, kind: 'number' });
    if (!q) return out;
    for (const qv of queues) {
      if (qv.isPark) continue;
      if (qv.name.toLowerCase().includes(q) || qv.ext.startsWith(q)) out.push({ ext: qv.ext, label: `${qv.name} (queue)`, kind: 'queue' });
    }
    for (const c of contacts) {
      if (c.user === operator.ext) continue;
      if (c.name.toLowerCase().includes(q) || c.user.startsWith(q)) out.push({ ext: c.user, label: c.name || c.user, kind: 'person' });
    }
    const seen = new Set<string>();
    return out.filter((t) => (seen.has(t.ext) ? false : (seen.add(t.ext), true))).slice(0, 7);
  }, [contacts, operator.ext, query, queues]);

  return (
    <Paper
      variant="outlined"
      sx={{ p: 1.5, borderWidth: 2, borderColor: tint('info', 0.5), bgcolor: 'background.paper' }}
    >
      <Stack direction="row" spacing={1} alignItems="center">
        <Box sx={{ color: inbound ? 'success.main' : 'info.main', display: 'flex' }}>
          <Icon name={inbound ? 'lucide:phone-incoming' : 'lucide:phone-outgoing'} size={18} />
        </Box>
        <Typography variant="body2" sx={{ fontWeight: 700, flex: 1, minWidth: 0 }} noWrap title={name}>
          {name}
        </Typography>
        {link ? (
          <Typography
            component="a"
            href={link}
            target="_blank"
            rel="noopener noreferrer"
            variant="caption"
            title="Open caller in CRM"
            sx={{ color: 'primary.main', fontWeight: 600 }}
          >
            CRM Link
          </Typography>
        ) : null}
      </Stack>
      <Stack direction="row" spacing={1} alignItems="center" sx={{ mt: 0.5 }}>
        {number && number !== name ? (
          <Typography variant="caption" color="text.secondary" sx={{ fontVariantNumeric: 'tabular-nums' }}>
            {number}
          </Typography>
        ) : null}
        <Pill tone={st.tone} label={st.label} />
        <Box sx={{ flex: 1 }} />
        <Timer since={line.answeredAt ?? line.startedAt} title="Call duration" />
      </Stack>

      {ringing ? (
        <Stack direction="row" spacing={1} sx={{ mt: 1.25 }} flexWrap="wrap" useFlexGap>
          {line.status === 'ringing' && inbound ? (
            <SmallButton
              icon="lucide:phone"
              label="Answer"
              color="success"
              variant="contained"
              title="Answer on your phone"
              busy={isPending(`answer:${key}`)}
              onClick={() => void answer()}
            />
          ) : null}
          {inbound ? (
            <SmallButton
              icon="lucide:phone-missed"
              label="Decline"
              color="inherit"
              title="Decline, and let the call carry on to the next step"
              busy={isPending(`decline:${key}`)}
              onClick={() => void decline()}
            />
          ) : (
            <SmallButton
              icon="lucide:phone-off"
              label="Hang up"
              color="error"
              busy={isPending(`hangup:${key}`)}
              onClick={() => void hangUp()}
            />
          )}
        </Stack>
      ) : null}

      {connected ? (
        <>
          <Stack direction="row" spacing={0.5} sx={{ mt: 1.25 }} alignItems="center" flexWrap="wrap" useFlexGap>
            <SmallButton
              icon={held ? 'lucide:play' : 'lucide:pause'}
              label={held ? 'Resume' : 'Hold'}
              color={held ? 'warning' : 'inherit'}
              busy={isPending(`hold:${key}`)}
              onClick={() => void toggleHold()}
            />
            <SmallButton
              icon="lucide:phone-forwarded"
              label="Transfer"
              color="inherit"
              title="Blind transfer to a person, a queue or a number"
              busy={isPending(`transfer:${key}`)}
              onClick={() => setPanel((p) => (p === 'transfer' ? 'none' : 'transfer'))}
            />
            <SmallButton
              icon="lucide:circle-parking"
              label="Park"
              color="inherit"
              title={dynamicPark ? 'Park the call in the next free slot' : 'Pick a park slot'}
              busy={isPending(`park:${key}`)}
              onClick={onPark}
            />
            <Box sx={{ flex: 1 }} />
            <SmallButton
              icon="lucide:phone-off"
              label="Hang up"
              color="error"
              variant="contained"
              busy={isPending(`hangup:${key}`)}
              onClick={() => void hangUp()}
            />
          </Stack>

          {panel === 'park' ? (
            <Paper variant="outlined" sx={{ mt: 1, p: 1 }}>
              <Typography variant="caption" sx={{ fontWeight: 700, display: 'block', mb: 0.5 }}>
                Park in
              </Typography>
              {parks.length === 0 ? (
                <Typography variant="caption" color="text.secondary">
                  This domain has no park slots. Add one under Manage, Call Parks.
                </Typography>
              ) : shownParks.every((p) => !isFree(p)) && parks.every((p) => !isFree(p)) ? (
                <Typography variant="caption" color="text.secondary">
                  Every park slot is taken.
                </Typography>
              ) : (
                <Stack spacing={0.5}>
                  {(shownParks.length ? shownParks : parks).map((p) => {
                    const taken = !isFree(p);
                    return (
                      <SmallButton
                        key={p.ext}
                        fullWidth
                        variant="text"
                        color="inherit"
                        disabled={taken}
                        title={taken ? 'Slot already occupied' : `Park in ${p.ext}`}
                        label={taken ? `${slotLabel(p)} (taken)` : slotLabel(p)}
                        onClick={() => void parkIn(p.ext)}
                      />
                    );
                  })}
                </Stack>
              )}
            </Paper>
          ) : null}

          {panel === 'transfer' ? (
            <Paper variant="outlined" sx={{ mt: 1, p: 1 }}>
              <TextField
                size="small"
                fullWidth
                autoFocus
                placeholder="Name, extension, queue or number"
                value={query}
                onChange={(e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => setQuery(e.target.value)}
                onKeyDown={(e: React.KeyboardEvent) => {
                  if (e.key === 'Enter' && suggestions[0]) void transferTo(suggestions[0]);
                  if (e.key === 'Escape') setPanel('none');
                }}
                inputProps={{ 'aria-label': 'Transfer to' }}
              />
              {suggestions.length ? (
                <Stack spacing={0.25} sx={{ mt: 0.5 }} role="list" aria-label="Transfer destinations">
                  {suggestions.map((t) => (
                    <SmallButton
                      key={`${t.kind}:${t.ext}`}
                      fullWidth
                      variant="text"
                      color="inherit"
                      icon={t.kind === 'queue' ? 'lucide:list-ordered' : t.kind === 'number' ? 'lucide:hash' : 'lucide:user'}
                      label={t.kind === 'number' ? `Transfer to ${t.label}` : `${t.label} · ${t.ext}`}
                      onClick={() => void transferTo(t)}
                    />
                  ))}
                </Stack>
              ) : (
                <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 0.5 }}>
                  Type a name, an extension or a phone number.
                </Typography>
              )}
            </Paper>
          ) : null}
        </>
      ) : null}
    </Paper>
  );
}
