/**
 * Park slots, in the call-queue row shape the rest of the app reads.
 *
 * v46 gives parks their own resource, `/domains/:d/parks`, whose rows carry a
 * live `parked-calls-total-current` (and are no longer in the plain call-queue
 * list). Older switches list them as `callqueues?type=park`. The counter is
 * mapped onto the queue counter field so a slot reads as occupied even when
 * the calls feed has no detail for the parked call.
 */
export async function readParkQueues(api: Api, d: string): Promise<NsCallQueue[]> {
  try {
    const rows = asArray<NsRecord>(await api.get(`/domains/${e(d)}/parks`, { limit: 500 }));
    return rows.map(
      (p) =>
        ({
          ...p,
          callqueue: String(p.park ?? p.callqueue ?? ''),
          'active-queued-calls-total-current': p['parked-calls-total-current'] ?? 0,
        }) as NsCallQueue,
    );
  } catch (err) {
    if (!isNotFound(err)) throw err;
  }
  return asArray<NsCallQueue>(await api.get(`/domains/${e(d)}/callqueues`, { type: 'park', limit: 500 }));
}

