/**
 * Flip "Taking calls" and read it back. The switch answers 202 to any value,
 * so the read-back is the only confirmation the change landed.
 */
export async function setTakingCalls(api: Api, d: string, q: string, aid: string, on: boolean): Promise<void> {
  const want = on ? 'automatic' : 'manual';
  await api.put(`/domains/${e(d)}/callqueues/${e(q)}/agents/${e(aid)}`, {
    'callqueue-agent-availability-type': want,
  });
  const back = await readAgent(api, d, q, aid);
  const got = lower(back?.['callqueue-agent-availability-type']);
  const ok = on ? got === 'automatic' || got === 'offnet-automatic' : got === 'manual';
  if (!ok) {
    throw new Error(
      `${on ? 'Taking calls' : 'Stop taking calls'} was not applied by the phone system (it still reads ${got || 'nothing'}).`,
    );
  }
}

export async function setCallLimit(api: Api, d: string, q: string, aid: string, limit: number): Promise<void> {
  await api.put(`/domains/${e(d)}/callqueues/${e(q)}/agents/${e(aid)}`, {
    'limits-max-active-calls-total': limit,
  });
  const back = await readAgent(api, d, q, aid);
  const got = toFloat(back?.['limits-max-active-calls-total']);
  if (got !== limit) {
    throw new Error(`Max calls was not applied by the phone system (it still reads ${got || 'nothing'}).`);
  }
}

