/**
 * One extension's voicemail box: New / Saved / Trash, ten messages a page,
 * with playback and delete. The Engage VoicemailPanel rebuilt on the Horizon
 * kit (same folders, labels, paging and two-click delete).
 *
 * Record shape, confirmed on the v46 lab (16 messages, grant_wilderman_llc,
 * 2026-09-24): `filename` is the id used in the URL (it ends in `.wav`),
 * `voicemail-from-name` / `voicemail-from-user` name the caller (plus a numeric
 * `voicemail-from-caller-id-number`), `created-datetime` is ISO with an offset
 * and `file-duration-seconds` is a number. `file-access-url` came back as an
 * empty string on every message (the single-message GET too), so playback
 * renders only when the switch hands out a URL. No lab message carried
 * `urgent` or `transcription`; both are read from the SDK shape.
 *
 * Delete is a v2 DELETE and works: from New or Saved it moves the message to
 * the Trash, from the Trash it deletes it for good. Save (moving between
 * folders) is a PATCH, which Horizon apps cannot send, so it renders disabled
 * with the reason.
 */
import type * as React from 'react';
import { useEffect, useRef, useState } from 'react';

import type { NsVoicemail } from '../types';
import * as ns from '../api/ns';
import type { VoicemailFolder } from '../api/ns';
import { useSwitchboard } from '../data/SwitchboardData';
import { useActions } from '../data/actions';
import { usefulCallerName } from '../model/calls';
import { classifyError, describeReadError } from '../model/errors';
import { formatDateTime, formatMinSec, formatPhone } from '../model/format';
import { first, parseSwitchTime, str, toIntOrUndef, yes } from '../model/raw';
import { useKit } from '../ui/kit';
import { Empty, Pill } from '../ui/bits';

const PAGE_SIZE = 10;
/** How long an armed Delete waits for its confirming click. */
const CONFIRM_MS = 4000;

const FOLDERS: Array<{ value: VoicemailFolder; label: string }> = [
  { value: 'new', label: 'New' },
  { value: 'save', label: 'Saved' },
  { value: 'trash', label: 'Trash' },
];

const BUTTON_SX = { textTransform: 'none', fontWeight: 600, whiteSpace: 'nowrap', minWidth: 0 };

// ---------------------------------------------------------------------------
// Row formatting
// ---------------------------------------------------------------------------

function vmId(vm: NsVoicemail): string {
  return first(vm.filename, vm.id);
}

/** `"NAME" <NUMBER>` when both are known, else whichever is, else "Unknown". */
function callerLabel(vm: NsVoicemail): string {
  const name = first(vm['voicemail-from-name'], vm['caller-id-name']);
  const rawNumber = first(vm['voicemail-from-user'], vm['caller-id-number'], vm['voicemail-from-caller-id-number']);
  const number = formatPhone(rawNumber);
  // A name that only repeats the number (or says "Unknown") adds nothing beside it.
  const shownName = name && (!rawNumber || usefulCallerName(name, rawNumber)) ? name : '';
  if (shownName && number) return `"${shownName}" <${number}>`;
  return shownName || number || 'Unknown';
}

function receivedLabel(vm: NsVoicemail): string {
  const raw = first(vm['created-datetime'], vm['received-datetime']);
  if (!raw) return '';
  const ms = parseSwitchTime(raw);
  return ms == null ? raw : formatDateTime(ms);
}

function durationLabel(vm: NsVoicemail): string {
  const s = toIntOrUndef(vm['file-duration-seconds']);
  return s == null ? '' : formatMinSec(s);
}

/** Only an absolute http(s) URL is handed to the audio element. */
function audioUrl(vm: NsVoicemail): string {
  const url = str(vm['file-access-url']).trim();
  return /^https?:\/\//i.test(url) ? url : '';
}

function isLongText(text: string): boolean {
  return text.length > 200 || text.split('\n').length > 3;
}

// ---------------------------------------------------------------------------
// Section
// ---------------------------------------------------------------------------

export function VoicemailSection({ user }: { user: string }) {
  const { Box, Stack, Typography, Tabs, Alert, Paper, Divider, Button, Icon } = useKit();
  const { api, domain, reloadVoicemailCount } = useSwitchboard();
  const { run, isPending } = useActions();

  const [folder, setFolder] = useState<VoicemailFolder>('new');
  const [page, setPage] = useState(1);
  const [rows, setRows] = useState<NsVoicemail[]>([]);
  const [hasMore, setHasMore] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [reloadTick, setReloadTick] = useState(0);
  const [armed, setArmed] = useState<string | null>(null);
  const [expanded, setExpanded] = useState<ReadonlySet<string>>(() => new Set());

  /** Bumped by every read (and on unmount): a late answer for a left view is dropped. */
  const request = useRef(0);
  /** Set when a delete removed a row, so an emptied page can refill itself. */
  const removedRow = useRef(false);
  const playing = useRef<HTMLAudioElement | null>(null);

  // One read per folder/page view (and per Retry).
  useEffect(() => {
    const id = ++request.current;
    removedRow.current = false;
    setLoading(true);
    setError(null);
    setArmed(null);
    ns.readVoicemails(api, domain, user, folder, (page - 1) * PAGE_SIZE, PAGE_SIZE)
      .then((list) => {
        if (id !== request.current) return;
        setRows(list);
        setHasMore(list.length >= PAGE_SIZE);
        setExpanded(new Set());
      })
      .catch((err: unknown) => {
        if (id !== request.current) return;
        setRows([]);
        setHasMore(false);
        setError(
          classifyError(err) === 'not-found'
            ? 'The phone system has no voicemail box for this extension.'
            : describeReadError('voicemails', err),
        );
      })
      .finally(() => {
        if (id === request.current) setLoading(false);
      });
    return () => {
      request.current += 1;
    };
  }, [api, domain, user, folder, page, reloadTick]);

  // A page emptied by deletes pulls the next messages up, or steps back a page.
  useEffect(() => {
    if (loading || rows.length || !removedRow.current) return;
    removedRow.current = false;
    if (hasMore) setReloadTick((t) => t + 1);
    else if (page > 1) setPage((p) => Math.max(1, p - 1));
  }, [hasMore, loading, page, rows]);

  // An armed Delete disarms on its own after a few seconds.
  useEffect(() => {
    if (!armed) return undefined;
    const t = window.setTimeout(() => setArmed(null), CONFIRM_MS);
    return () => window.clearTimeout(t);
  }, [armed]);

  const chooseFolder = (next: VoicemailFolder) => {
    if (next === folder) return;
    setFolder(next);
    setPage(1);
  };

  // One message plays at a time: starting one pauses the last.
  const onPlay = (e: React.SyntheticEvent<HTMLAudioElement>) => {
    const el = e.currentTarget;
    if (playing.current && playing.current !== el) playing.current.pause();
    playing.current = el;
  };

  const toggleExpanded = (key: string) =>
    setExpanded((prev) => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });

  const remove = async (vm: NsVoicemail) => {
    const id = vmId(vm);
    if (!id) return;
    setArmed(null);
    const from = folder;
    const view = request.current;
    const permanent = from === 'trash';
    const outcome = { gone: false };
    const ok = await run(
      `vm-delete:${user}:${from}:${id}`,
      async () => {
        try {
          await ns.deleteVoicemail(api, domain, user, from, id);
        } catch (err) {
          if (classifyError(err) !== 'not-found') throw err;
          outcome.gone = true;
          throw new Error('It is no longer in this folder, so it may have been moved or deleted from a phone.');
        }
      },
      {
        success: permanent ? 'Voicemail deleted' : 'Voicemail moved to Trash',
        failure: permanent ? 'Could not delete this voicemail.' : 'Could not move this voicemail to the Trash.',
      },
    );
    if (!ok) {
      // Already gone: show the folder as it is now.
      if (outcome.gone && request.current === view) setReloadTick((t) => t + 1);
      return;
    }
    void reloadVoicemailCount(user);
    // The same file name follows a message into the Trash, so only edit the
    // view the delete was made from.
    if (request.current !== view) return;
    removedRow.current = true;
    setRows((prev) => prev.filter((v) => vmId(v) !== id));
  };

  const save = async (vm: NsVoicemail) => {
    const id = vmId(vm);
    if (!id) return;
    const from = folder;
    const view = request.current;
    const outcome = { gone: false };
    const ok = await run(
      `vm-save:${user}:${from}:${id}`,
      async () => {
        try {
          await ns.saveVoicemail(api, domain, user, from, id);
        } catch (err) {
          if (classifyError(err) !== 'not-found') throw err;
          outcome.gone = true;
          throw new Error('It is no longer in this folder, so it may have been moved or deleted from a phone.');
        }
      },
      from === 'trash'
        ? { success: 'Voicemail restored to Saved', failure: 'Could not restore this voicemail.' }
        : { success: 'Voicemail saved', failure: 'Could not save this voicemail.' },
    );
    if (!ok) {
      if (outcome.gone && request.current === view) setReloadTick((t) => t + 1);
      return;
    }
    void reloadVoicemailCount(user);
    if (request.current !== view) return;
    removedRow.current = true;
    setRows((prev) => prev.filter((v) => vmId(v) !== id));
  };

  let body: React.ReactNode;
  if (loading) {
    body = (
      <Stack spacing={1} aria-busy="true">
        <Typography variant="caption" color="text.secondary" role="status">
          Loading voicemails...
        </Typography>
        {[0, 1, 2].map((i) => (
          <Box
            key={i}
            sx={{
              height: 72,
              borderRadius: 1.5,
              bgcolor: 'action.hover',
              animation: 'tvsbVmPulse 1.4s ease-in-out infinite',
              '@keyframes tvsbVmPulse': { '0%, 100%': { opacity: 1 }, '50%': { opacity: 0.45 } },
            }}
          />
        ))}
      </Stack>
    );
  } else if (error) {
    body = (
      <Alert
        severity="error"
        title="Voicemail could not be loaded"
        message={error}
        action={{ label: 'Retry', onClick: () => setReloadTick((t) => t + 1) }}
      />
    );
  } else if (!rows.length) {
    body = <Empty>No voicemails found.</Empty>;
  } else {
    body = (
      <Paper variant="outlined" sx={{ p: 0, overflow: 'hidden' }}>
        <Stack divider={<Divider flexItem />}>
          {rows.map((vm, i) => {
            const id = vmId(vm);
            const key = id || `row-${i}`;
            const caller = callerLabel(vm);
            const url = audioUrl(vm);
            const text = str(vm.transcription).trim();
            const open = expanded.has(key);
            const meta = [receivedLabel(vm), durationLabel(vm)].filter(Boolean).join(' · ');
            const deleteKey = `vm-delete:${user}:${folder}:${id}`;
            return (
              <Stack key={key} direction="row" spacing={1.5} alignItems="flex-start" sx={{ p: 1.5, flexWrap: 'wrap', rowGap: 1 }}>
                <Box sx={{ color: 'primary.main', display: 'flex', pt: 0.25 }} aria-hidden>
                  <Icon name="lucide:voicemail" size={18} />
                </Box>
                <Box sx={{ flex: '1 1 260px', minWidth: 0 }}>
                  <Stack direction="row" spacing={1} alignItems="center" sx={{ minWidth: 0 }}>
                    <Typography variant="body2" noWrap title={caller} sx={{ fontWeight: 600, minWidth: 0 }}>
                      {caller}
                    </Typography>
                    {yes(vm.urgent) ? <Pill tone="error" label="Urgent" icon="lucide:triangle-alert" /> : null}
                  </Stack>
                  {meta ? (
                    <Typography variant="caption" color="text.secondary" component="div" sx={{ fontVariantNumeric: 'tabular-nums' }}>
                      {meta}
                    </Typography>
                  ) : null}
                  {text ? (
                    <Box sx={{ mt: 0.75 }}>
                      <Typography
                        variant="body2"
                        color="text.secondary"
                        sx={
                          open
                            ? { whiteSpace: 'pre-wrap' }
                            : {
                                whiteSpace: 'pre-wrap',
                                display: '-webkit-box',
                                WebkitLineClamp: 3,
                                WebkitBoxOrient: 'vertical',
                                overflow: 'hidden',
                              }
                        }
                      >
                        {text}
                      </Typography>
                      {isLongText(text) ? (
                        <Button size="small" variant="text" onClick={() => toggleExpanded(key)} sx={{ ...BUTTON_SX, px: 0.5 }}>
                          {open ? 'Show less' : 'Show more'}
                        </Button>
                      ) : null}
                    </Box>
                  ) : null}
                  <Box sx={{ mt: 1, maxWidth: 420, '& audio': { display: 'block', width: '100%' } }}>
                    {url ? (
                      <audio controls preload="none" src={url} onPlay={onPlay} aria-label={`Voicemail from ${caller}`}>
                        Your browser cannot play this recording.
                      </audio>
                    ) : (
                      <Stack direction="row" spacing={0.75} alignItems="center" sx={{ color: 'text.secondary' }}>
                        <Icon name="lucide:volume-x" size={14} />
                        <Typography variant="caption" color="text.secondary">
                          No audio file
                        </Typography>
                      </Stack>
                    )}
                  </Box>
                </Box>
                <Stack direction="row" spacing={1} alignItems="center" sx={{ ml: 'auto' }}>
                  {folder !== 'save' ? (
                    <Button
                      size="small"
                      variant="outlined"
                      color="inherit"
                      disabled={!id || isPending(`vm-save:${user}:${folder}:${id}`)}
                      onClick={() => void save(vm)}
                      startIcon={<Icon name={folder === 'trash' ? 'lucide:undo-2' : 'lucide:save'} size={14} />}
                      sx={BUTTON_SX}
                      aria-label={`${folder === 'trash' ? 'Restore to Saved' : 'Save'} voicemail from ${caller}`}
                    >
                      {folder === 'trash' ? 'Restore' : 'Save'}
                    </Button>
                  ) : null}
                  <DeleteButton
                    trash={folder === 'trash'}
                    armed={!!id && armed === id}
                    busy={isPending(deleteKey)}
                    disabled={!id}
                    onArm={() => setArmed(id)}
                    onConfirm={() => void remove(vm)}
                    onDisarm={() => setArmed((a) => (a === id ? null : a))}
                  />
                </Stack>
              </Stack>
            );
          })}
        </Stack>
      </Paper>
    );
  }

  return (
    <Stack spacing={1.5}>
      <Tabs variant="pill" value={folder} onChange={(v) => chooseFolder(String(v) as VoicemailFolder)} options={FOLDERS} />
      {folder === 'trash' ? (
        <Stack direction="row" spacing={0.75} alignItems="center" sx={{ color: 'text.secondary' }}>
          <Icon name="lucide:info" size={14} />
          <Typography variant="caption" color="text.secondary" sx={{ fontStyle: 'italic' }}>
            The Trash is cleared out every 30 days.
          </Typography>
        </Stack>
      ) : null}
      {body}
      {page > 1 || hasMore ? (
        <Stack direction="row" spacing={1.5} alignItems="center" justifyContent="center" component="nav" aria-label="Voicemail pages">
          <Button
            size="small"
            variant="outlined"
            disabled={page <= 1 || loading}
            onClick={() => setPage((p) => Math.max(1, p - 1))}
            startIcon={<Icon name="lucide:chevron-left" size={16} />}
            sx={BUTTON_SX}
          >
            Previous
          </Button>
          <Typography variant="body2" sx={{ fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>
            Page {page}
          </Typography>
          <Button
            size="small"
            variant="outlined"
            disabled={!hasMore || loading}
            onClick={() => setPage((p) => p + 1)}
            endIcon={<Icon name="lucide:chevron-right" size={16} />}
            sx={BUTTON_SX}
          >
            Next
          </Button>
        </Stack>
      ) : null}
    </Stack>
  );
}

/**
 * Delete with a two-click confirm: the first click arms it (red "Confirm"),
 * the second deletes. Leaving the button or waiting a few seconds disarms it.
 */
function DeleteButton({
  trash,
  armed,
  busy,
  disabled,
  onArm,
  onConfirm,
  onDisarm,
}: {
  trash: boolean;
  armed: boolean;
  busy: boolean;
  disabled: boolean;
  onArm: () => void;
  onConfirm: () => void;
  onDisarm: () => void;
}) {
  const { Button, Tooltip, Icon } = useKit();
  const what = trash ? 'Delete permanently' : 'Move to Trash';
  const title = armed ? 'Click again to confirm' : what;
  return (
    <Tooltip title={title} arrow>
      <span>
        <Button
          size="small"
          variant={armed ? 'contained' : 'outlined'}
          color={armed ? 'error' : 'inherit'}
          disabled={disabled || busy}
          onClick={armed ? onConfirm : onArm}
          onBlur={onDisarm}
          aria-label={armed ? `Confirm: ${what.toLowerCase()}` : what}
          startIcon={<Icon name={busy ? 'svg-spinners:ring-resize' : armed ? 'lucide:check' : 'lucide:trash-2'} size={16} />}
          sx={BUTTON_SX}
        >
          {armed ? 'Confirm' : 'Delete'}
        </Button>
      </span>
    </Tooltip>
  );
}
